/* @lc app=leetcode id=3753 lang=kotlin */ class Solution { fun go(ds: List<Int>, pos: Int, last: Int, trend: Int, tight: Boolean, started: Boolean, memo: HashMap<Int, LongArray>): LongArray = if (pos == ds.size) longArrayOf(1L, 0L) else memo.getOrPut((((pos * 11 + last) * 3 + trend) * 2 + (if (tight) 1 else 0)) * 2 + (if (started) 1 else 0)) { (0..(if (tight) ds[pos] else 9)).fold(longArrayOf(0L, 0L)) { acc, d -> (if (!started && d == 0) go(ds, pos + 1, 10, 0, tight && d == ds[pos], false, memo) else (if (started && trend == 1 && d < last) 1 else if (started && trend == 2 && d > last) 1 else 0).let { w -> go(ds, pos + 1, d, (if (!started) 0 else if (d > last) 1 else if (d < last) 2 else 0), tight && d == ds[pos], true, memo).let { r -> longArrayOf(r[0], r[1] + w * r[0]) } }).let { r -> longArrayOf(acc[0] + r[0], acc[1] + r[1]) } } } fun tw(n: Long): Long = go(n.toString().map { it - '0' }, 0, 10, 0, true, false, HashMap())[1] fun totalWaviness(num1: Long, num2: Long): Long = tw(num2) - tw(num1 - 1) }